 *
 * Every key is deploy-only and not overridable until it is opted in.
 */
#[ConfigRoot(root: 'beam.licenser', title: 'Licensing', description: 'Whether this install enforces a phone-home license.')]
class BeamLicenserSection extends ConfigSection
